questionvariables.text:
opts : [
  ["correct", true, "Because sin(x) is periodic, many different x-values give the same y-value, so reversing the function (swapping inputs and outputs) would not give a single well-defined output for each input."],
  ["wrong1", false, "Because sin(x) is only defined for x between -1 and 1."],
  ["wrong2", false, "Because sin(x) is an odd function, and odd functions never have inverses."],
  ["wrong3", false, "Because the graph of sin(x) does not pass the horizontal line test at exactly one point."]
];
ta : "correct";
